package com.iar.tardypass.printing

import com.iar.tardypass.domain.PassReceipt
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test
import java.util.Base64

/**
 * Byte-parity contract with the PWA. Fixtures were generated by running the PWA's
 * real builder (Tardy-Pass-PWA/src/services/escpos.ts) under Node 22:
 * buildEscPosReceipt(input) |> bytesToBase64. If EscPos.kt ever diverges from the
 * PWA's receipt format for ASCII input, these tests fail.
 */
class EscPosTest {

    @Test
    fun `full receipt matches PWA bytes`() {
        val expected = Base64.getDecoder().decode(
            ""
        )
        val actual = EscPos.buildReceipt(
            PassReceipt(
                title = "IAR Tardy Pass",
                name = "Alice Nguyen", id = "10001",
                date = "08/13/2026", time = "09:41 AM",
                period = "P2", course = "Biology", room = "117",
                reason = "Late", staff = "CW", status = "Excused"
            )
        )
        assertArrayEquals(expected, actual)
    }

    @Test
    fun `minimal receipt omits empty lines and defaults to Unexcused`() {
        val expected = Base64.getDecoder().decode(
            "G0AbYQEbRQFJQVIgVGFyZHkgUGFzcwobRQAbYQBTdHVkZW50OiBCb2IgTGVlICgxMDAwMikKRGF0ZTogMDgvMTMvMjAyNgpUaW1lOiAwMTowNSBQTQpTdGF0dXM6IFVuZXhjdXNlZAotLS0tLS0tLS0tLS0tLS0tLS0tLS0tLS0tLS0tLS0KG2EBUHJvY2VlZCBkaXJlY3RseSB0byBjbGFzcy4KG2EAG2QD"
        )
        val actual = EscPos.buildReceipt(
            PassReceipt(
                title = "IAR Tardy Pass",
                name = "Bob Lee", id = "10002",
                date = "08/13/2026", time = "01:05 PM"
            )
        )
        assertArrayEquals(expected, actual)
    }

    @Test
    fun `cp437 strips unmappable diacritics instead of printing question marks`() {
        val bytes = EscPos.encode("García Łukasz", PrinterEncoding.CP437)
        val cp437 = charset("IBM437")
        // í is in CP437 so it survives; Ł is not, so it folds to L
        assertEquals("García Lukasz", String(bytes, cp437))
    }

    @Test
    fun `utf8 passthrough`() {
        assertArrayEquals("García".toByteArray(Charsets.UTF_8), EscPos.encode("García", PrinterEncoding.UTF8))
    }

    @Test
    fun `code page selection is prepended after init when enabled`() {
        val receipt = PassReceipt(
            title = "T", name = "N", id = "1", date = "d", time = "t"
        )
        val with = EscPos.buildReceipt(receipt, PrinterEncoding.CP437, selectCodePage = true)
        val without = EscPos.buildReceipt(receipt, PrinterEncoding.CP437, selectCodePage = false)
        // ESC @ then ESC t 0
        assertArrayEquals(byteArrayOf(0x1b, 0x40, 0x1b, 0x74, 0x00), with.copyOfRange(0, 5))
        assertArrayEquals(without, with.copyOfRange(0, 2) + with.copyOfRange(5, with.size))
    }
}
